import { defineConfig } from 'astro/config';

export default defineConfig({
  output: 'static',
  compressHTML: true,
  build: {
    inlineStylesheets: 'auto',
  },
});

﻿:root {
  --ink: #0B0B0C;
  --charcoal: #161616;
  --charcoal-2: #1E1E1F;
  --bone: #EDE9E3;
  --bone-dim: #C9C3B8;
  --ember: #E4572E;
  --ember-soft: rgba(228, 87, 46, 0.16);
  --line: rgba(237, 233, 227, 0.12);
  --muted: rgba(237, 233, 227, 0.62);
  --font-display: "Fraunces", "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, -apple-system, sans-serif;
  --max: 1120px;
  --radius: 14px;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .ken-burns { animation: none !important; transform: none !important; }
  .reveal-wipe .after { clip-path: none !important; opacity: 1 !important; }
}

body {
  margin: 0;
  font-family: var(--font-body);
  background: var(--ink);
  color: var(--bone);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; display: block; height: auto; }
a { color: inherit; }
button, input { font: inherit; }
:focus-visible {
  outline: 2px solid var(--ember);
  outline-offset: 3px;
}

.container {
  width: min(100% - 2rem, var(--max));
  margin-inline: auto;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 40;
  backdrop-filter: blur(14px);
  background: rgba(11, 11, 12, 0.72);
  border-bottom: 1px solid var(--line);
}
.site-header .inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 64px;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  text-decoration: none;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 0.86rem;
}
.logo-mark {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: radial-gradient(circle at 40% 35%, #ffb199 0%, var(--ember) 45%, #7a2410 100%);
  box-shadow: 0 0 18px rgba(228, 87, 46, 0.45);
}
.header-cta {
  text-decoration: none;
  color: var(--bone);
  border: 1px solid var(--line);
  padding: 0.55rem 0.95rem;
  border-radius: 999px;
  font-size: 0.86rem;
  transition: border-color 0.25s var(--ease), background 0.25s var(--ease);
}
.header-cta:hover {
  border-color: rgba(228, 87, 46, 0.55);
  background: var(--ember-soft);
}

/* HERO */
.hero {
  position: relative;
  min-height: min(92vh, 920px);
  display: grid;
  align-items: end;
  padding: 5rem 0 4rem;
  overflow: hidden;
}
.hero-media {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(11,11,12,0.25) 0%, rgba(11,11,12,0.55) 42%, rgba(11,11,12,0.96) 100%),
    linear-gradient(90deg, rgba(11,11,12,0.75) 0%, rgba(11,11,12,0.15) 55%, rgba(11,11,12,0.55) 100%);
}
.hero-pair {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.hero-pair img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.reveal-wipe {
  position: absolute;
  inset: 0;
}
.reveal-wipe .before,
.reveal-wipe .after {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.reveal-wipe .after {
  clip-path: inset(0 100% 0 0);
  animation: wipeIn 1.4s var(--ease) 0.45s forwards;
}
@keyframes wipeIn {
  to { clip-path: inset(0 0 0 0); }
}
.ken-burns {
  animation: ken 18s ease-in-out infinite alternate;
  transform-origin: 50% 40%;
}
@keyframes ken {
  from { transform: scale(1.03); }
  to { transform: scale(1.1); }
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 38rem;
  padding-bottom: 0.5rem;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--bone-dim);
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 1rem;
}
.eyebrow::before {
  content: "";
  width: 1.4rem;
  height: 1px;
  background: var(--ember);
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 450;
  font-size: clamp(2.4rem, 6vw, 4.4rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 0 0 1rem;
}
.hero-sub {
  color: var(--muted);
  font-size: 1.05rem;
  max-width: 32rem;
  margin: 0 0 1.5rem;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
  margin-bottom: 1.25rem;
}
.btn {
  appearance: none;
  border: 0;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  border-radius: 999px;
  padding: 0.9rem 1.35rem;
  font-weight: 560;
  font-size: 0.95rem;
  transition: transform 0.25s var(--ease), box-shadow 0.25s var(--ease), background 0.25s var(--ease);
}
.btn-primary {
  background: var(--ember);
  color: #fff;
  box-shadow: 0 10px 30px rgba(228, 87, 46, 0.28);
}
.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 34px rgba(228, 87, 46, 0.38);
}
.btn-ghost {
  background: transparent;
  color: var(--bone);
  border: 1px solid var(--line);
}
.btn-ghost:hover { border-color: rgba(237,233,227,0.35); }
.honesty {
  font-size: 0.84rem;
  color: var(--bone-dim);
  max-width: 34rem;
  border-left: 2px solid rgba(228, 87, 46, 0.55);
  padding-left: 0.85rem;
  margin: 0;
}
.ethics-line {
  margin-top: 0.75rem;
  font-size: 0.82rem;
  color: var(--muted);
}
.sample-chip {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 3;
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: rgba(11,11,12,0.72);
  border: 1px solid var(--line);
  color: var(--bone-dim);
  padding: 0.35rem 0.55rem;
  border-radius: 999px;
  backdrop-filter: blur(8px);
}
.ba-label {
  position: absolute;
  bottom: 1rem;
  z-index: 3;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--bone-dim);
  background: rgba(11,11,12,0.55);
  padding: 0.28rem 0.5rem;
  border-radius: 6px;
}
.ba-label.before { left: 1rem; }
.ba-label.after { right: 1rem; }

/* DOORS */
.doors {
  padding: 4.5rem 0 3.5rem;
  border-top: 1px solid var(--line);
}
.section-kicker {
  color: var(--bone-dim);
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin: 0 0 0.75rem;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 450;
  letter-spacing: -0.02em;
  margin: 0 0 1.75rem;
  line-height: 1.1;
}
.door-list {
  display: grid;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.door-btn {
  width: 100%;
  text-align: left;
  background: transparent;
  color: var(--bone);
  border: 1px solid transparent;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  padding: 1rem 0.35rem;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  transition: background 0.25s var(--ease), border-color 0.25s var(--ease), padding 0.25s var(--ease);
}
.door-btn:hover,
.door-btn[aria-pressed="true"] {
  background: linear-gradient(90deg, var(--ember-soft), transparent 70%);
  border-color: transparent;
  padding-left: 0.7rem;
}
.door-word {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.4rem);
  line-height: 1;
  letter-spacing: -0.03em;
}
.door-meta {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  opacity: 0.55;
  transition: opacity 0.25s var(--ease);
}
.door-btn:hover .door-meta,
.door-btn[aria-pressed="true"] .door-meta { opacity: 1; }
.door-thumb {
  width: 52px;
  height: 68px;
  border-radius: 8px;
  object-fit: cover;
  border: 1px solid var(--line);
}
.door-arrow {
  font-size: 1.3rem;
  color: var(--ember);
}

/* CREDIBILITY */
.credibility {
  background: var(--bone);
  color: var(--ink);
  padding: 4.5rem 0;
}
.credibility .section-kicker { color: rgba(11,11,12,0.55); }
.credibility .section-title { color: var(--ink); }
.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  margin-bottom: 2.5rem;
}
.stat {
  padding: 1.25rem;
  border: 1px solid rgba(11,11,12,0.1);
  border-radius: var(--radius);
  background: rgba(255,255,255,0.35);
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 0.6s var(--ease), transform 0.6s var(--ease);
}
.stat.in { opacity: 1; transform: none; }
.stat-value {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  line-height: 1;
  margin-bottom: 0.55rem;
}
.stat-label { color: rgba(11,11,12,0.7); font-size: 0.95rem; }
.stat-source {
  margin-top: 0.7rem;
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba(11,11,12,0.45);
}
.proof-strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.85rem;
}
.proof-card {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: #ddd;
  aspect-ratio: 4/5;
}
.proof-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.92);
}
.proof-card .chip {
  position: absolute;
  top: 0.55rem;
  left: 0.55rem;
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: rgba(11,11,12,0.65);
  color: var(--bone);
  padding: 0.25rem 0.45rem;
  border-radius: 999px;
}
.proof-note {
  margin-top: 1rem;
  font-size: 0.88rem;
  color: rgba(11,11,12,0.62);
}

/* FOUNDING SHAPE */
.founding-shape {
  padding: 4.5rem 0;
  border-top: 1px solid var(--line);
}
.founding-panel {
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 4px);
  padding: clamp(1.5rem, 4vw, 2.5rem);
  background:
    radial-gradient(circle at 10% 0%, rgba(228,87,46,0.12), transparent 40%),
    linear-gradient(180deg, var(--charcoal), var(--ink));
}
.founding-panel p {
  color: var(--muted);
  max-width: 40rem;
  margin: 0.75rem 0 0;
}

/* CTA */
.cta {
  background: var(--bone);
  color: var(--ink);
  padding: 4.5rem 0 5rem;
}
.cta .section-kicker { color: rgba(11,11,12,0.55); }
.cta .section-title { color: var(--ink); margin-bottom: 0.75rem; }
.cta-lead {
  color: rgba(11,11,12,0.7);
  max-width: 36rem;
  margin: 0 0 1.75rem;
}
.form-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.65rem;
  max-width: 34rem;
}
.form-row input[type="email"] {
  border: 1px solid rgba(11,11,12,0.18);
  background: #fff;
  border-radius: 999px;
  padding: 0.95rem 1.15rem;
  color: var(--ink);
}
.form-row input::placeholder { color: rgba(11,11,12,0.4); }
.trust {
  margin-top: 1rem;
  font-size: 0.86rem;
  color: rgba(11,11,12,0.55);
}
.form-success {
  display: none;
  margin-top: 1rem;
  padding: 0.9rem 1rem;
  border-radius: 12px;
  background: rgba(228,87,46,0.12);
  border: 1px solid rgba(228,87,46,0.3);
  color: var(--ink);
}
.form-success.show { display: block; }

.site-footer {
  border-top: 1px solid var(--line);
  padding: 1.5rem 0 2rem;
  color: var(--muted);
  font-size: 0.84rem;
}
.site-footer .inner {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

@media (max-width: 820px) {
  .stats, .proof-strip { grid-template-columns: 1fr; }
  .hero { min-height: 88vh; padding-top: 4rem; }
  .form-row { grid-template-columns: 1fr; }
  .door-thumb { display: none; }
}

---
import Base from '../layouts/Base.astro';
import { DOORS, DOOR_ORDER } from '../data/doors.js';

const doorKey = Astro.url.searchParams.get('d') || 'dating';
const active = DOORS[doorKey] || DOORS.dating;
const doors = DOOR_ORDER.map((k) => DOORS[k]);
const pageTitle = 'Cinder — ' + active.word;
const doorJson = JSON.stringify(DOORS);
---
<Base door={active.id} title={pageTitle} description={active.sub}>
  <section class="hero" id="top" aria-label="Hero">
    <div class="hero-media" aria-hidden="true">
      <div class="reveal-wipe">
        <img class="before ken-burns" id="hero-before" src={active.before} alt="" width="1200" height="1600" />
        <img class="after ken-burns" id="hero-after" src={active.after} alt="" width="1200" height="1600" fetchpriority="high" />
      </div>
      <span class="sample-chip">Sample</span>
      <span class="ba-label before">Before</span>
      <span class="ba-label after">After</span>
    </div>
    <div class="container hero-content">
      <p class="eyebrow">AI photo studio · founding access</p>
      <h1 id="hero-promise">{active.promise}</h1>
      <p class="hero-sub" id="hero-sub">{active.sub}</p>
      <div class="hero-actions">
        <a class="btn btn-primary" id="hero-cta" href="#founding">{active.cta}</a>
        <a class="btn btn-ghost" href="#doors">Choose your use</a>
      </div>
      <p class="honesty">
        These are sample results made with Cinder — not real customers yet. We will only show permissioned real photos when we have them.
      </p>
      {active.ethics && (
        <p class="ethics-line" id="ethics-line">
          Cinder enhances light, framing, and presentation. It never invents a different face. You stay you.
        </p>
      )}
      {!active.ethics && (
        <p class="ethics-line" id="ethics-line" style="display:none"></p>
      )}
    </div>
  </section>

  <section class="doors" id="doors" aria-labelledby="doors-title">
    <div class="container">
      <p class="section-kicker">Four doors</p>
      <h2 class="section-title" id="doors-title">Which one are you here for?</h2>
      <ul class="door-list" role="list">
        {doors.map((d) => (
          <li>
            <button
              type="button"
              class="door-btn"
              data-door={d.id}
              aria-pressed={d.id === active.id ? 'true' : 'false'}
            >
              <span class="door-word">{d.word}</span>
              <span class="door-meta">
                <img class="door-thumb" src={d.after} alt="" width="52" height="68" loading="lazy" />
                <span class="door-arrow" aria-hidden="true">→</span>
              </span>
            </button>
          </li>
        ))}
      </ul>
      <noscript>
        <p>
          <a href="/dating">Dating</a> ·
          <a href="/career">Career</a> ·
          <a href="/acting">Acting</a> ·
          <a href="/portfolio">Portfolio</a>
        </p>
      </noscript>
    </div>
  </section>

  <section class="credibility" id="proof" aria-labelledby="proof-title">
    <div class="container">
      <p class="section-kicker">Why the photo matters</p>
      <h2 class="section-title" id="proof-title">First impressions form fast. Quality shows.</h2>
      <div class="stats">
        <article class="stat">
          <div class="stat-value">~100ms</div>
          <div class="stat-label">Time for a first impression of a face to form.</div>
          <div class="stat-source">Willis and Todorov, Princeton · 2006</div>
        </article>
        <article class="stat">
          <div class="stat-value">Higher</div>
          <div class="stat-label">Profiles with strong primary photos earn materially more engagement across dating and professional platforms.</div>
          <div class="stat-source">Industry photo-quality studies · problem-side</div>
        </article>
        <article class="stat">
          <div class="stat-value">You</div>
          <div class="stat-label">Still recognizably you — better light, framing, and presentation. Not a stranger.</div>
          <div class="stat-source">Cinder product promise</div>
        </article>
      </div>
      <div class="proof-strip" aria-label="Sample proof strip">
        <figure class="proof-card">
          <img src="/samples/proof-1-after.jpg" alt="Sample result one" loading="lazy" width="600" height="750" />
          <span class="chip">Sample</span>
        </figure>
        <figure class="proof-card">
          <img src="/samples/proof-2-after.jpg" alt="Sample result two" loading="lazy" width="600" height="750" />
          <span class="chip">Sample</span>
        </figure>
        <figure class="proof-card">
          <img src="/samples/proof-3-after.jpg" alt="Sample result three" loading="lazy" width="600" height="750" />
          <span class="chip">Sample</span>
        </figure>
      </div>
      <p class="proof-note">Illustrative sample results. Real, permissioned customer photos replace these after launch.</p>
    </div>
  </section>

  <section class="founding-shape" id="stories" aria-labelledby="stories-title">
    <div class="container">
      <div class="founding-panel">
        <p class="section-kicker" style="color: var(--bone-dim)">Stories</p>
        <h2 class="section-title" id="stories-title" style="margin-bottom:0">Founding members shape what goes here.</h2>
        <p>
          We are not inventing testimonials. Early members get priority in the first render queue — and the first real stories on this page will be yours, with permission.
        </p>
      </div>
    </div>
  </section>

  <section class="cta" id="founding" aria-labelledby="founding-title">
    <div class="container">
      <p class="section-kicker">Founding access</p>
      <h2 class="section-title" id="founding-title">Get priority. Lock founding price for life.</h2>
      <p class="cta-lead">
        Founding members receive priority in the first render queue and the founding price locked for life.
        Email only — no spam theater, no fake countdown.
      </p>
      <form class="founding-form" id="founding-form" novalidate>
        <input type="hidden" name="door" id="form-door" value={active.id} />
        <div class="form-row">
          <label for="email" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)">Email</label>
          <input id="email" name="email" type="email" required autocomplete="email" placeholder="you@email.com" />
          <button class="btn btn-primary" type="submit" id="submit-btn">{active.cta}</button>
        </div>
        <p class="trust">Your photos stay yours. Never sold. Deleted on request.</p>
        <div class="form-success" id="form-success" role="status" aria-live="polite">
          You are on the founding list. We will reach out when your priority window opens.
        </div>
      </form>
    </div>
  </section>

  <script id="door-data" type="application/json" set:html={doorJson} />

  <script is:inline>
    (function () {
      var dataEl = document.getElementById('door-data');
      if (!dataEl) return;
      var DOORS = JSON.parse(dataEl.textContent);
      var buttons = document.querySelectorAll('.door-btn[data-door]');
      var promiseEl = document.getElementById('hero-promise');
      var subEl = document.getElementById('hero-sub');
      var ctaEl = document.getElementById('hero-cta');
      var beforeEl = document.getElementById('hero-before');
      var afterEl = document.getElementById('hero-after');
      var ethicsEl = document.getElementById('ethics-line');
      var formDoor = document.getElementById('form-door');
      var submitBtn = document.getElementById('submit-btn');

      function setDoor(id) {
        var d = DOORS[id] || DOORS.dating;
        document.body.dataset.door = d.id;
        if (promiseEl) promiseEl.textContent = d.promise;
        if (subEl) subEl.textContent = d.sub;
        if (ctaEl) ctaEl.textContent = d.cta;
        if (submitBtn) submitBtn.textContent = d.cta;
        if (beforeEl) beforeEl.src = d.before;
        if (afterEl) afterEl.src = d.after;
        if (formDoor) formDoor.value = d.id;
        if (ethicsEl) {
          if (d.ethics) {
            ethicsEl.style.display = '';
            ethicsEl.textContent = 'Cinder enhances light, framing, and presentation. It never invents a different face. You stay you.';
          } else {
            ethicsEl.style.display = 'none';
          }
        }
        buttons.forEach(function (b) {
          b.setAttribute('aria-pressed', b.getAttribute('data-door') === d.id ? 'true' : 'false');
        });
        try {
          var url = new URL(window.location.href);
          url.searchParams.set('d', d.id);
          history.replaceState({}, '', url);
        } catch (e) {}
        if (afterEl && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
          afterEl.style.animation = 'none';
          void afterEl.offsetWidth;
          afterEl.style.animation = '';
        }
      }

      buttons.forEach(function (btn) {
        btn.addEventListener('click', function () { setDoor(btn.getAttribute('data-door')); });
      });

      var stats = document.querySelectorAll('.stat');
